import { describe, expect, it } from 'vitest';
import { translate, translations, type Language, type MessageKey } from './translations';

describe('translate', () => {
  it('plain strings and fallbacks', () => {
    expect(translate('en', 'counter.reset')).toBe('Reset');
    expect(translate('ru', 'counter.reset')).toBe('Сбросить');
  });
  it('russian plurals', () => {
    const ru = (n: number) => translate('ru', 'counter.clicks', { count: n });
    expect([0, 1, 2, 4, 5, 11, 21, 22, 25, 101, 111].map(ru)).toEqual([
      '0 кликов', '1 клик', '2 клика', '4 клика', '5 кликов', '11 кликов',
      '21 клик', '22 клика', '25 кликов', '101 клик', '111 кликов',
    ]);
  });
  it('english plurals', () => {
    expect(translate('en', 'counter.clicks', { count: 0 })).toBe('0 clicks');
    expect(translate('en', 'counter.clicks', { count: 1 })).toBe('1 click');
  });
  it('every key exists in both languages', () => {
    const keys = Object.keys(translations.en) as MessageKey[];
    for (const lang of ['en', 'ru'] as Language[]) {
      for (const k of keys) expect(translations[lang][k], `${lang}:${k}`).toBeTruthy();
    }
  });
});
EOF
